vcard-edit input[type="text"],
vcard-edit input[type="email"],
vcard-edit input[type="url"],
vcard-edit input[type="tel"],
vcard-edit input[type="number"],
vcard-edit input[type="date"],
vcard-edit .vcard-type-selection,
vcard-tz select:not([size], [multiple]),
vcard-special-date select:not([size], [multiple]) {
  margin: 0;
  border: var(--input-border-density) solid var(--toolbar-field-border-color);
  padding-block: 0;
  min-height: initial;
  height: calc(var(--in-content-button-height) - 2px);
  color: inherit;
  margin-block-end: 3px;
  margin-inline-end: 3px;
  font-weight: normal;

  &:not(select) {
    padding-inline: 6px;
  }
}

vcard-edit {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(30em, 1fr));
  column-gap: 2em;
  grid-template-rows: masonry;
  row-gap: 30px;
  color: var(--sidebar-text-color);
  --input-border-density: 1px;

  & label[for] {
    margin-block-end: 6px;
    font-weight: 600;
  }

  & vcard-impp input[type="text"] {
    flex: 1;
  }

  & input[type="email"] {
    width: -moz-available;
  }

  & input[type="url"],
  & input[type="tel"] {
    flex: 1;
  }

  & input[type="number"] {
    padding-inline-end: 0;
  }

  & select:not([size], [multiple]) {
    border-color: var(--in-content-button-border-color);
    -moz-context-properties: stroke;
    stroke: currentColor;
    background-position-x: right 6px;
    --logical-padding: 5px;

    &:dir(rtl) {
      background-position-x: left 6px;
    }

    &:user-invalid {
      outline: 2px solid var(--in-content-border-invalid);
      outline-offset: -1px;
    }
  }

  & textarea {
    /* 3px is for the margin-end. */
    width: calc(100% - 3px);
    box-sizing: border-box;
    border: var(--input-border-density) solid var(--toolbar-field-border-color);
    margin-block: 0 3px;
    margin-inline: 0 3px;
    resize: vertical;
  }
}

#addr-book-edit-n {
  grid-column: 1 / -1;
}

/* N field styles */
vcard-n {
  display: flex;
  align-items: end;
  justify-content: flex-start;
  flex-wrap: wrap;
  gap: 6px;
  --button-dimension: 24px;
}

.n-list-component {
  display: inline-flex;
  flex-direction: column;

  & button {
    min-width: auto;
    min-height: auto;
    display: inline-flex;
    margin: 0;
    padding: 3px;
    border: none;
    z-index: 2;
    margin-block-end: 9px;
    border-radius: 8px;
  }

  & button img {
    -moz-context-properties: fill;
    fill: currentColor;
    width: 9px;
    height: 9px;
  }

  & button[hidden] {
    display: none;
  }
}

#n-list-component-prefix,
#n-list-component-suffix {
  flex: 0 0 0%;

  & input {
    width: 10ch;
    box-sizing: border-box;
  }
}

#n-list-component-firstname,
#n-list-component-middlename,
#n-list-component-lastname {
  flex: 1 0 0%;

  & input {
    min-width: 20ch;
    box-sizing: border-box;
    width: 100%;
  }
}

#n-list-component-middlename.hasButton {
  flex: 0 0 auto;
}

/* Display name / Full name / Nick name styles */
vcard-fn,
vcard-nickname {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-block-start: 12px;

  & label[for] {
    margin-block-end: 0;
  }
}

.vcard-checkbox {
  display: flex;
  align-items: center;
}

